css:
.er { display: grid; gap: 0; }
.er__item { display: grid; gap: 1rem 3rem; padding: 2rem 0; border-top: 1px solid var(--bff-line, rgba(21,38,26,.22)); }
@media (min-width: 62rem) { .er__item { grid-template-columns: minmax(0, 17rem) minmax(0, 1fr); } }
.er__item > div:first-child { margin: 0 0 .6rem; }
.er__day { margin: 0; font-family: var(--os-font-heading); font-weight: 380; font-size: clamp(1.7rem, 1.2rem + 1.6vw, 2.5rem); line-height: 1.05; color: var(--os-color-heading); }
.er__meta { margin: .5rem 0 0; font-size: 1rem; line-height: 1.05; color: var(--bff-ink-2, #3f4f3b); }
.er__next { display: inline; }
.er__next b { color: var(--os-color-link); font-weight: 700; }
.er__title { margin: 0 0 .5em; font-size: clamp(1.45rem, 1.1rem + 1.2vw, 2rem); line-height: 1.15; letter-spacing: -.015em; }
.er__sum { margin: 1em 0; max-width: 62ch; }
.er__item a { display: inline-block; color: var(--os-color-link); }
.er__more { color: var(--os-color-link); text-decoration: underline; text-underline-offset: .18em; text-decoration-thickness: .08em; }
.er__item a:hover .er__more { text-decoration-thickness: .14em; }
@media (max-width: 40rem) { .er__item a { padding-block: .7rem; } }
